package e.e.a;
import java.io.*;import java.lang.management.ManagementFactory;import java.util.Arrays;import org.junit.*;import static org.junit.Assert.*;
public class NicoliveAuditProtocolTest {
 @Test public void skipBoundsAndOverflow()throws Exception{byte[] data=NicoliveProtocolTest.join(NicoliveProtocolTest.v(65536),new byte[65536],new byte[]{42});NicoliveData.Wire w=new NicoliveData.Wire(data);w.skip(2);assertEquals(42,w.varint());for(byte[] bad:new byte[][]{{10,1},{(byte)128},{(byte)255,(byte)255,(byte)127}}){try{new NicoliveData.Wire(bad).skip(2);fail();}catch(IOException expected){}}byte[] invalid=new byte[10];Arrays.fill(invalid,(byte)128);invalid[9]=2;try{new NicoliveData.Wire(invalid).varint();fail();}catch(IOException expected){}assertEquals(-1L,new NicoliveData.Wire(NicoliveProtocolTest.v(-1L)).varint());}
 @Test public void allocationProbe()throws Exception{byte[] data=NicoliveProtocolTest.join(NicoliveProtocolTest.v(65536),new byte[65536]);com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)ManagementFactory.getThreadMXBean();long thread=Thread.currentThread().getId();for(int i=0;i<1000;i++)new NicoliveData.Wire(data).skip(2);long[] times=new long[7],alloc=new long[7];for(int j=0;j<7;j++){long bytes=bean.getThreadAllocatedBytes(thread),start=System.nanoTime();for(int i=0;i<2000;i++){NicoliveData.Wire w=new NicoliveData.Wire(data);w.skip(2);if(w.pos!=data.length)throw new AssertionError();}times[j]=System.nanoTime()-start;alloc[j]=bean.getThreadAllocatedBytes(thread)-bytes;}Arrays.sort(times);Arrays.sort(alloc);System.out.println("AUDIT 2000x64KiB median_ns="+times[3]+" allocated_bytes="+alloc[3]);}
}
